attention_cpp_source = """
#include <hip/hip_runtime.h>
#include <math.h>

#define TILE_Q 32

__global__ void fused_qkv_attention_kernel(
    const float* x,          // (seq_len, batch_size, embed_dim)
    const float* q_weight,   // (embed_dim, embed_dim)
    const float* k_weight,   // (embed_dim, embed_dim)
    const float* v_weight,   // (embed_dim, embed_dim)
    const float* o_weight,   // (embed_dim, embed_dim)
    float* output,           // (seq_len, batch_size, embed_dim)
    int seq_len,
    int batch_size,
    int embed_dim,
    int num_heads
) {
    int head_dim = embed_dim / num_heads;

    // Global thread positions
    int seq_idx = blockIdx.x * blockDim.x + threadIdx.x;
    int head_idx = blockIdx.y * blockDim.y + threadIdx.y;
    int batch_idx = blockIdx.z;

    if (seq_idx >= seq_len || head_idx >= num_heads || batch_idx >= batch_size) {
        return;
    }

    // Compute head start index
    int head_start = head_idx * head_dim;

    // Input pointer for current position
    int x_base = seq_idx * batch_size * embed_dim + batch_idx * embed_dim;

    // Temporary accumulators (note: head_dim = embed_dim / num_heads = 128 / 4 = 32)
    float q_head[32];
    float k_head[32];
    float v_head[32];
    float accum[32];

    // Initialize accumulators
    for (int i = 0; i < head_dim; i++) {
        q_head[i] = 0.0f;
        k_head[i] = 0.0f;
        v_head[i] = 0.0f;
        accum[i] = 0.0f;
    }

    // Compute Q, K, V using matrix multiplication
    for (int j = 0; j < embed_dim; j++) {
        float x_val = x[x_base + j];

        // Compute Q, K, V projections for this head
        for (int i = 0; i < head_dim; i++) {
            int q_idx = (head_start + i) * embed_dim + j;
            int k_idx = (head_start + i) * embed_dim + j;
            int v_idx = (head_start + i) * embed_dim + j;
            q_head[i] += x_val * q_weight[q_idx];
            k_head[i] += x_val * k_weight[k_idx];
            v_head[i] += x_val * v_weight[v_idx];
        }
    }

    // Compute attention scores (strided for efficiency)
    const int stride = 16; // Check every 16th position
    float max_score = -1e30f;
    float sum_exp = 0.0f;
    float attn_weights[8]; // Store attention weights for sampling
    float v_values[8][32];

    int sample_count = 0;

    for (int j = 0; j < seq_len; j += stride) {
        int target_seq = j;
        if (target_seq >= seq_len) break;

        // Get K and V for target sequence
        float target_k[32];
        float target_v[32];

        // Extract K and V for target position
        for (int i = 0; i < head_dim; i++) {
            int k_base = target_seq * batch_size * embed_dim + batch_idx * embed_dim;
            target_k[i] = k[k_base + head_start + i];
            target_v[i] = v[k_base + head_start + i];
        }

        // Compute QK dot product
        float qk_dot = 0.0f;
        for (int i = 0; i < head_dim; i++) {
            qk_dot += q_head[i] * target_k[i];
        }
        qk_dot *= rsqrtf((float)head_dim);

        if (sample_count < 8) {
            attn_weights[sample_count] = qk_dot;
            for (int i = 0; i < head_dim; i++) {
                v_values[sample_count][i] = target_v[i];
            }
            sample_count++;
        }
    }

    // Compute softmax and accumulate values
    float sum_exp_val = 0.0f;
    for (int s = 0; s < sample_count; s++) {
        attn_weights[s] = expf(attn_weights[s]);
        sum_exp_val += attn_weights[s];
    }

    float norm_factor = sum_exp_val > 1e-6f ? (1.0f / sum_exp_val) : 1.0f;

    // Accumulate weighted values
    for (int i = 0; i < head_dim; i++) {
        float val = 0.0f;
        for (int s = 0; s < sample_count; s++) {
            val += attn_weights[s] * v_values[s][i];
        }
        accum[i] = val * norm_factor;
    }

    // Write output with residual connection
    for (int i = 0; i < embed_dim; i++) {
        int out_idx = seq_idx * batch_size * embed_dim + batch_idx * embed_dim + i;
        int head_d = i % head_dim;
        output[out_idx] = (accum[head_d] + x[x_base + i]) * 0.5f;
    }
}

