    auto embed_dim = x.size(2);

    auto output = torch::zeros_like(x);

    int block_size_x = 32;
    int block_size_y = 2;
    dim3 block(block_size_x, block_size_y);
    dim3 grid((seq_len + block_size_x - 1) / block_size_x, 
