# Fused attention kernel - optimized for better memory access
fused_attention_source = """
#include <hip/hip_runtime.h>

__global__ void fused_attention_kernel(
    const float* q, const float* k, const float* v,
    float* output,
    int B, int nh, int T, int hs
) {
    // q, k, v: (B, nh, T, hs) row-major
    // output: (B, nh, T, hs)

    int b = blockIdx.z;
    int h = blockIdx.y;
    int t_out = blockIdx.x * blockDim.x + threadIdx.x;

    if (t_out >= T) return;

    // Indices for this position
    int base_q = ((b * nh + h) * T + t_out) * hs;

    // Compute attention scores for current output position
    // att[t_in] = sum over hs of q[t_out, hs] * k[t_in, hs] / sqrt(hs)

    // Use shared memory for attention weights
    extern __shared__ float shared_mem[];
    float* att_weights = shared_mem;

    // Compute attention scores for all t_in positions
    for (int t_in = 0; t_in < T; t_in++) {
        if (t_in > t_out) {
            // Causal mask: can only attend to positions <= current position
            att_weights[t_in] = -1.0e30f;
        } else {
            float sum = 0.0f;
            int base_k = ((b * nh + h) * T + t_in) * hs;
            for (int d = 0; d < hs; d++) {
                sum += q[base_q + d] * k[base_k + d];
            }
            att_weights[t_in] = sum * rsqrtf(float(hs));
        }
    }

    __syncthreads();

    // Compute softmax over t_in dimension
    // Find maximum for numerical stability
    float max_val = -1.0e30f;
    for (int t_in = 0; t_in < T; t_in++) {
        if (t_in <= t_out) {
            max_val = fmaxf(max_val, att_weights[t_in]);
        }
    }

    // Compute exp and sum
    float exp_sum = 0.0f;
    for (int t_in = 0; t_in < T; t_in++) {
        if (t_in <= t_out) {
            att_weights[t_in] = expf(att_weights[t_in] - max_val);
            exp_sum += att_weights[t_in];
        }
    }

    // Normalize
    for (int t_in = 0; t_in < T; t_in++) {
        if (t_in <= t_out) {
            att_weights[t_in] /= exp_sum;
        }
    }

    __syncthreads();

    // Compute output: att_weights @ v
    // output[t_out, d] = sum over t_in of att_weights[t_in] * v[t_in, d]
    for (int d = 0; d < hs; d++) {
        float out_val = 0.0f;
        for (int t_in = 0; t_in < T; t_in++) {
            if (t_in <= t_out) {
                int v_idx = ((b * nh + h) * T + t_in) * hs + d;
                out_val += att_weights[t_in] * v[v_idx];
            }
        }
        int out_idx = ((b * nh + h) * T + t_out) * hs + d;
        output[out_idx] = out_val;
    }
}

torch::Tensor fused_attention_hip(torch::Tensor q, torch::Tensor k, torch::Tensor v) {
    auto B = q.size(0);
    auto nh = q.size(1);
    auto T = q.size(2);
    auto hs = q.size(3);

    auto output = torch::zeros_like(q);

    const int block_size = 16;
    dim3 blockDim(block_size);
    dim3 gridDim((T + block_size - 1) / block_size, nh, B);
    size_t shared_mem_size = T * sizeof(float);

    fused_attention_kernel<<<gridDim, blockDim, shared_mem_size>>>(
        q.data_ptr<float>(), 
        k.data_ptr<float>(), 
        v.data_ptr<float>(),
        output.data_ptr<float>(),
        B, nh, T, hs
    );

    return output;
}
"""

