import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import math
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# Flash Attention style kernel for causal self-attention
# Fuses Q @ K^T, scaling, masking, softmax, and @ V operations
scaled_dot_product_attn_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>

#define MAX_SEQ_LEN 1024
#define BLOCK_M 64
#define HEAD_SIZE 96  // n_embd / n_head = 768 / 8 = 96

__device__ __forceinline__ float warpReduceSum(float val) {
    for (int offset = 16; offset > 0; offset /= 2) {
        val += __shfl_down(val, offset, 32);
    }
    return val;
}

__global__ void scaled_dot_product_attn_kernel(
    const float* q, const float* k, const float* v, 
    float* output,
    int batch_size, int num_heads, int seq_len, int head_size) {

    // Batch and head indices
    int b = blockIdx.z;
    int h = blockIdx.y;

    // Row position in sequence
    int i = blockIdx.x * blockDim.x + threadIdx.x;

    if (i >= seq_len) return;

    // Compute Q[i] for this head
    int q_base = b * num_heads * seq_len * head_size + h * seq_len * head_size + i * head_size;

    // Shared memory for Q[i] and accumulator
    __shared__ float s_q[HEAD_SIZE];
    __shared__ float s_o[HEAD_SIZE];

    // Load Q[i] into shared memory
    for (int d = threadIdx.x; d < head_size; d += blockDim.x) {
        s_q[d] = q[q_base + d];
        s_o[d] = 0.0f;
    }
    __syncthreads();

    // Compute attention scores and accumulate output
    float sum_exp = 0.0f;

    // Process K and V in blocks
    for (int block_start = 0; block_start < seq_len; block_start += BLOCK_M) {
        int block_end = min(block_start + BLOCK_M, seq_len);
        int num_elements = block_end - block_start;

        // Compute attention scores for this block
        float attn_scores[64];  // Max BLOCK_M
        float block_max = -1e20f;

        for (int j_idx = 0; j_idx < num_elements; j_idx++) {
            int actual_j = block_start + j_idx;
            int k_idx = b * num_heads * seq_len * head_size + h * seq_len * head_size + actual_j * head_size;

            // Dot product Q[i] @ K[actual_j]
            float dot = 0.0f;
            for (int d = threadIdx.x; d < head_size; d += blockDim.x) {
                dot += s_q[d] * k[k_idx + d];
            }

            // Reduce dot product across threads
            dot = warpReduceSum(dot);
            if (threadIdx.x == 0) {
                attn_scores[j_idx] = dot;
                block_max = fmaxf(block_max, dot);
            }
        }

        // Synchronize after reduction
        __syncthreads();

        // Broadcast block_max from thread 0
        if (threadIdx.x == 0) {
            block_max = attn_scores[0];
            for (int j_idx = 1; j_idx < num_elements; j_idx++) {
                block_max = fmaxf(block_max, attn_scores[j_idx]);
            }
        }
        __syncthreads();

        // Apply causal mask and compute softmax
        float block_sum_exp = 0.0f;
        for (int j_idx = 0; j_idx < num_elements; j_idx++) {
            int actual_j = block_start + j_idx;

            // Causal mask: only attend to positions <= i
            if (actual_j > i) {
                attn_scores[j_idx] = -1e20f;
            } else {
                // Scale by sqrt(d_k)
                attn_scores[j_idx] = (attn_scores[j_idx] / sqrtf(float(head_size))) - block_max;
                attn_scores[j_idx] = expf(attn_scores[j_idx]);
            }
            block_sum_exp += attn_scores[j_idx];
        }

        // Reduce sum_exp across threads
        block_sum_exp = warpReduceSum(block_sum_exp);

        // Normalize and compute partial output
        if (threadIdx.x == 0) {
            float inv_sum_exp = 1.0f / (sum_exp + block_sum_exp);
            float scale = inv_sum_exp * expf(-logf(sum_exp + 1e-6f) + block_max);

            for (int j_idx = 0; j_idx < num_elements; j_idx++) {
                if (block_start + j_idx <= i) {
                    attn_scores[j_idx] *= inv_sum_exp;
                }
            }
        }
        __syncthreads();

        // Accumulate output
        for (int j_idx = 0; j_idx < num_elements; j_idx++) {
            int actual_j = block_start + j_idx;
            if (actual_j <= i) {
                int v_idx = b * num_heads * seq_len * head_size + h * seq_len * head_size + actual_j * head_size;
                float attn_weight = attn_scores[j_idx];

                // Vector outer product: attn_weight * V[actual_j]
                for (int d = threadIdx.x; d < head_size; d += blockDim.x) {
                    s_o[d] += attn_weight * v[v_idx + d];
                }
            }
        }
        __syncthreads();

        // Update sum_exp for next iteration
        if (threadIdx.x == 0) {
            float new_sum_exp = 0.0f;
            for (int j_idx = 0; j_idx < num_elements; j_idx++) {
                new_sum_exp += attn_scores[j_idx];
            }
            sum_exp = new_sum_exp;
        }
        __syncthreads();
    }

    // Write output
    int out_base = b * num_heads * seq_len * head_size + h * seq_len * head_size + i * head_size;
    for (int d = threadIdx.x; d < head_size; d += blockDim.x) {
        output[out_base + d] = s_o[d];
    }
}

torch::Tensor scaled_dot_product_attn_hip(
    torch::Tensor q, torch::Tensor k, torch::Tensor v) {

    auto batch_size = q.size(0);
    auto num_heads = q.size(1);
    auto seq_len = q.size(2);
    auto head_size = q.size(3);

    auto output = torch::zeros_like(q);

    dim3 block_dim(BLOCK_M);
    dim3 grid_dim((seq_len + BLOCK_M - 1) / BLOCK_M, num_heads, batch_size);

