class ModelNew(nn.Module):
    """
    Optimized Vision Attention model with custom HIP kernels
    Uses optimized QKV projection and relies on PyTorch for attention mechanism
    """
    def __init__(self, embed_dim, num_heads):
        super(ModelNew, self).__init__()
        self.embed_dim = embed_dim
        self.num_heads = num_heads

        # Initialize attention projections
        self.q_proj = nn.Linear(embed_dim, embed_dim, bias=False)
        self.k_proj = nn.Linear(embed_dim, embed_dim, bias=False)
        self.v_proj = nn.Linear(embed_dim, embed_dim, bias=False)
        self.out_proj = nn.Linear(embed_dim, embed_dim, bias=False)

        self.norm = nn.LayerNorm(embed_dim)

        # Save reference to optimized kernel
        self.attention_kernel = attention_module

    def forward(self, x):
        """
        Forward pass with optimized QKV projection
        """
        B, C, H, W = x.shape

        # Reshape to (seq_len, batch_size, embed_dim)
        x_seq = x.view(B, C, H * W).permute(2, 0, 1)

        # Apply optimized QKV projection kernel
        q = self.attention_kernel.qkv_projection_hip(
            x_seq,
            self.q_proj.weight,
            self.k_proj.weight,
            self.v_proj.weight
        )

        # Compute K and V using the same kernel by copying weights
        k = self.attention_kernel.qkv_projection_hip(
            x_seq,
            self.k_proj.weight,
            self.k_proj.weight,
            self.v_proj.weight
        )[0]  # Get the first returned tensor

        v = self.attention_kernel.qkv_projection_hip(
            x_seq,
            self.v_proj.weight,
            self.v_proj.weight,
            self.v_proj.weight
        )[0]

        # Head reshaping for multi-head attention
        head_dim = self.embed_dim // self.num_heads
        q = q.view(q.size(0), q.size(1), self.num_heads, head_dim).transpose(1, 2)
        k = k.view(k.size(0), k.size(1), self.num_heads, head_dim).transpose(1, 2)
        v = v.view(v.size(0), v.size(1), self.num_heads, head_dim).transpose(1, 2)

        # Compute attention scores
        scores = torch.matmul(q, k.transpose(-2, -1)) / (float(head_dim) ** 0.5)
        attn_weights = torch.softmax(scores, dim=-1)
        attn_output = torch.matmul(attn_weights, v)

        # Merge heads
        attn_output = attn_output.transpose(1, 2).contiguous().view(attn_output.size(0), attn_output.size(2), -1)

        # Output projection
        attn_output = self.out_proj(attn_output)

        # Residual connection and normalization
        x = self.norm(attn_output + x_seq)

        # Reshape back to (B, C, H, W)
        x = x.permute(1, 2, 0).view(B, C, H, W)

        return x

