scaled_dot_product_attn_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>

#define BLOCK_SIZE 128

__global__ void scaled_dot_product_attn_kernel(
    const float* q, const float* k, const float* v, 
    float* output,
    int batch_size, int num_heads, int seq_len, int head_size) {

    // Batch and head indices
    int b = blockIdx.z;
    int h = blockIdx.y;

    // Row position in sequence
    int i = blockIdx.x * blockDim.x + threadIdx.x;

    if (i >= seq_len) return;

    // Compute Q[i] for this head
    int q_base = b * num_heads * seq_len * head_size + h * seq_len * head_size + i * head_size;

    // Shared memory for attention scores and output accumulation
    extern __shared__ float shared_mem[];
    float* attn_scores = shared_mem;
    float* acc_output = attn_scores + seq_len;

    // Initialize accumulator
    for (int d = threadIdx.x; d < head_size; d += blockDim.x) {
        acc_output[d] = 0.0f;
    }

    // Compute Q[i] @ K^T[i] and apply causal mask and scaling
    float max_score = -1e20f;
    for (int j = threadIdx.x; j < seq_len; j += blockDim.x) {
        int k_base = b * num_heads * seq_len * head_size + h * seq_len * head_size + j * head_size;

        // Dot product Q[i] @ K[j]
        float dot = 0.0f;
        for (int d = 0; d < head_size; d++) {
            dot += q[q_base + d] * k[k_base + d];
        }

        // Scale by sqrt(d_k) and apply causal mask
        float scale = 1.0f / sqrtf(float(head_size));
        float score = (j <= i) ? (dot * scale) : -1e20f;

        attn_scores[j] = score;
        max_score = fmaxf(max_score, score);
    }

    // Reduce max_score across threads
    __shared__ float s_max_score;
    max_score = (threadIdx.x == 0) ? max_score : -1e20f;

    for (int offset = blockDim.x / 2; offset > 0; offset /= 2) {
        if (threadIdx.x < offset) {
            max_score = fmaxf(max_score, attn_scores[threadIdx.x + offset]);
        }
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        s_max_score = max_score;
    }
    __syncthreads();
    max_score = s_max_score;

    // Compute softmax
    float sum_exp = 0.0f;
    for (int j = threadIdx.x; j < seq_len; j += blockDim.x) {
        float exp_score = expf(attn_scores[j] - max_score);
        attn_scores[j] = exp_score;
        sum_exp += exp_score;
    }

    // Reduce sum_exp across threads
    float local_sum = sum_exp;
    for (int offset = blockDim.x / 2; offset > 0; offset /= 2) {
        if (threadIdx.x < offset) {
            sum_exp += attn_scores[threadIdx.x + offset];
        }
        __syncthreads();
    }
    if (threadIdx.x == 0) {
        sum_exp = attn_scores[0];
        for (int j = 1; j < min(BLOCK_SIZE, (seq_len + blockDim.x - 1) / blockDim.x); j++) {
            sum_exp += attn_scores[j];
        }
    }
    __syncthreads();

    // Normalize attention scores
    for (int j = threadIdx.x; j < seq_len; j += blockDim.x) {
        attn_scores[j] = attn_scores[j] / (sum_exp + 1e-6f);
    }
    __syncthreads();

    // Compute output: softmax @ V
    for (int j = threadIdx.x; j < seq_len; j += blockDim.x) {
        int v_base = b * num_heads * seq_len * head_size + h * seq_len * head_size + j * head_size;
        float weight = attn_scores[j];

        for (int d = 0; d < head_size; d++) {
            atomicAdd(&acc_output[d], weight * v[v_base + d]);
        }
    }
    __syncthreads();

    // Write output
    int out_base = b * num_heads * seq_len * head_size + h * seq_len * head_size + i * head_size;
    for (int d = threadIdx.x; d < head_size; d += blockDim.x) {
        output[out_base + d] = acc_output[d];
    }
}

torch::Tensor scaled_dot_product_attn_hip(
    torch::Tensor q, torch::Tensor k, torch::Tensor v) {

    auto batch_size = q.size(0);
    auto num_heads = q.size(1);
    auto seq_len = q.size(2);
    auto head_size = q.size(3);

    auto output = torch::zeros_like(q);

    dim3 block_dim(BLOCK_SIZE);
    dim3 grid_dim((seq_len + BLOCK_SIZE - 1) / BLOCK_SIZE, num_heads, batch_size);

    int shared_mem_size = (seq_len + head_size) * sizeof(float);

    scaled_dot_product_attn_kernel<<<grid_dim, block_dim, shared_mem_size>>>(
        q.data_ptr<float>(),
        k.data_ptr<float>(),
        v.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size, num_heads, seq_len, head_size
    );

    return output;
}
