__global__ void qk_matmul_kernel(
    const float* q, const float* k, float* attn,
    int batch_size, int num_heads, int seq_len, int head_size, float scale) {

    int b = blockIdx.y;
    int h = blockIdx.z;
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    int j = blockIdx.y2 * blockDim.y + threadIdx.y;  // This needs fixing with proper grid dims

