__global__ void qk_matmul_kernel(
    const float* q, const float* k, float* attn,
    int batch_size, int num_heads, int seq_len, int head_size, float scale) {

    // Compute global indices
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int total_threads = blockDim.x * gridDim.x;

    // Position in the attention matrix
    int i = tid / seq_len;  // row
    int j = tid % seq_len;  // col
    int b_nh = tid / (seq_len * seq_len);  // batch and head combined

    if (b_nh >= batch_size * num_heads) return;

    int b = b_nh / num_heads;
    int h = b_nh % num_heads;

    // Compute dot product Q[i] @ K[j]
    float dot = 0.0f;
    int q_base = b * num_heads * seq_len * head_size + h * seq_len * head_size + i * head_size;
    int k_base = b * num_heads * seq_len * head_size + h * seq_len * head_size + j * head_size;

    for (int d = 0; d < head_size; d++) {
        dot += q[q_base + d] * k[k_base + d];
    }

    // Apply scale and causal mask
    if (j > i) {
        dot = -1e20f;
    } else {
        dot = dot * scale;
    }

    int attn_idx = (b * num_heads * seq_len + h * seq_len + i) * seq_len + j;
    attn[attn_idx] = dot;
}

