# Optimized kernel for residual addition and normalization
residual_norm_cpp_source = """
#include <hip/hip_runtime.h>

__global__ void residual_layer_norm_kernel(
    const float* attn_output,  // (seq_len, batch_size, embed_dim)
    const float* input,        // (seq_len, batch_size, embed_dim)
    const float* weight,       // (embed_dim,)
    const float* bias,         // (embed_dim,)
    float* output,             // (seq_len, batch_size, embed_dim)
    int seq_len,
    int batch_size,
    int embed_dim
) {
    int seq_idx = blockIdx.x * blockDim.x + threadIdx.x;
    int batch_idx = blockIdx.y * blockDim.y + threadIdx.y;

    if (seq_idx >= seq_len || batch_idx >= batch_size) {
        return;
    }

    int base = seq_idx * batch_size * embed_dim + batch_idx * embed_dim;

    // Compute residual and then layer norm
    // First compute mean for this position
    float mean = 0.0f;
    float mean_sq = 0.0f;

    for (int i = 0; i < embed_dim; i++) {
        float val = attn_output[base + i] + input[base + i];
        mean += val;
        mean_sq += val * val;
    }

    mean /= (float)embed_dim;
    mean_sq /= (float)embed_dim;
    float variance = mean_sq - mean * mean;
    float std_dev = sqrtf(variance + 1e-5f);
    float inv_std = 1.0f / std_dev;

    // Apply layer norm
    for (int i = 0; i < embed_dim; i++) {
        float val = attn_output[base + i] + input[base + i];
        output[base + i] = weight[i] * (val - mean) * inv_std + bias[i];
    }
}

torch::Tensor residual_layer_norm_hip(
    torch::Tensor attn_output,
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias
) {
    auto seq_len = attn_output.size(0);
    auto batch_size = attn_output.size(1);
    auto embed_dim = attn_output.size(2);

    auto output = torch::zeros_like(attn_output);

    dim3 block(256, 1);
    dim3 grid((seq_len + 255) / 256, batch_size);

    residual_layer_norm_kernel<<<grid, block>>>(
        attn_output.data_ptr<float>(),
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        seq_len,
        batch_size,
        embed_dim
    );

    return output;
}
"""

