# Optimized attention kernel with careful numerical implementation
fused_attention_source = """
#include <hip/hip_runtime.h>
#include <cmath>

__device__ float gelu(float x) {
    return 0.5f * x * (1.0f + tanhf(0.7978845608028654f * (x + 0.044715f * x * x * x)));
}

__global__ void scaled_dot_product_attention_kernel(
    const float* q, const float* k, const float* v,
    float* output,
    int B, int nh, int T, int hs
) {
    int b = blockIdx.z;
    int h = blockIdx.y;
    int t_out = blockIdx.x * blockDim.x + threadIdx.x;

    if (t_out >= T) return;

    // Base offset for this batch, head, and output position
    int base_offset = ((b * nh + h) * T + t_out) * hs;

    // Compute scaled dot product attention for all input positions
    // scores[t_in] = dot(q[t_out], k[t_in]) / sqrt(hs)
    extern __shared__ float shared_mem[];
    float* scores = shared_mem;
    float* exp_buffer = scores + T;

    float scale = rsqrtf(float(hs));

    for (int t_in = 0; t_in < T; t_in++) {
        if (t_in > t_out) {
            // Causal mask
            scores[t_in] = -1.0e30f;
        } else {
            // Compute dot product
            float dot = 0.0f;
            for (int d = 0; d < hs; d++) {
                dot += q[base_offset + d] * k[((b * nh + h) * T + t_in) * hs + d];
            }
            scores[t_in] = dot * scale;
        }
    }

    __syncthreads();

    // Softmax implementation with numerical stability
    // Find max
    float max_score = -1.0e30f;
    for (int t_in = 0; t_in < T; t_in++) {
        if (t_in <= t_out) {
            max_score = fmaxf(max_score, scores[t_in]);
        }
    }

    // Compute exp and sum
    float exp_sum = 0.0f;
    for (int t_in = 0; t_in < T; t_in++) {
        if (t_in <= t_out) {
            float exp_val = expf(scores[t_in] - max_score);
            exp_buffer[t_in] = exp_val;
            exp_sum += exp_val;
        } else {
            exp_buffer[t_in] = 0.0f;
        }
    }

    // Avoid division by zero
    if (exp_sum == 0.0f) exp_sum = 1.0f;

    __syncthreads();

    // Compute weighted sum over values
    for (int d = 0; d < hs; d++) {
        float weighted_sum = 0.0f;
        for (int t_in = 0; t_in < T; t_in++) {
            if (t_in <= t_out) {
                float attn_weight = exp_buffer[t_in] / exp_sum;
                weighted_sum += attn_weight * v[((b * nh + h) * T + t_in) * hs + d];
            }
        }
        output[base_offset + d] = weighted_sum;
    }
}

torch::Tensor fused_attention_hip(torch::Tensor q, torch::Tensor k, torch::Tensor v) {
    auto B = q.size(0);
    auto nh = q.size(1);
    auto T = q.size(2);
    auto hs = q.size(3);

    auto output = torch::zeros_like(q);

    const int block_size = 16;  // Process multiple t_out positions per block
    dim3 blockDim(block_size);
    dim3 gridDim((T + block_size - 1) / block_size, nh, B);
    size_t shared_mem_size = 2 * T * sizeof(float);

    scaled_dot_product_attention_kernel<<<gridDim, blockDim, shared_mem_size>>>(
        q.data_ptr<float>(), 
        k.data_ptr<float>(), 
        v.data_ptr<float>(),
        output.data_ptr<float>(),
        B, nh, T, hs
    );

    return output;
}
"""

fused_attention = load_inline(
    name="fused_attention",
    cpp_sources=fused_attention_source,
