    verbose=True,
)


class CausalSelfAttentionNew(nn.Module):
    """
    Optimized causal self-attention with fused kernel.
    """
    def __init__(self, n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen, fused_attention_module):
        super().__init__()
        assert n_embd % n_head == 0
        self.c_attn = nn.Linear(n_embd, 3 * n_embd)
        self.c_proj = nn.Linear(n_embd, n_embd)
        self.attn_dropout = nn.Dropout(attn_pdrop)
        self.resid_dropout = nn.Dropout(resid_pdrop)
        self.fused_attention = fused_attention_module
        self.n_head = n_head
        self.n_embd = n_embd

    def forward(self, x):
        B, T, C = x.size()
        hs = C // self.n_head

        # Compute q, k, v all at once
        qkv = self.c_attn(x)
        q, k, v = qkv.split(C, dim=-1)

        # Reshape for multi-head attention
        q = q.view(B, T, self.n_head, hs).transpose(1, 2)
        k = k.view(B, T, self.n_head, hs).transpose(1, 2)
        v = v.view(B, T, self.n_head, hs).transpose(1, 2)

        # Fused attention computation
        y = self.fused_attention.fused_attention_hip(q, k, v)

        # Reshape back and apply output projection
        y = y.transpose(1, 2).contiguous().view(B, T, C)
        y = self.resid_dropout(self.c_proj(y))

        return y


