            q_head = q[:, :, head, :]  # (seq_len, batch_size, head_dim)
            k_head = k[:, :, head, :]  # (seq_len, batch_size, head_dim)
            v_head = v[:, :, head, :]  # (seq_len, batch_size, head_dim)

            # Use our optimized kernel to compute QK scores
            # Need to transpose batch and seq dims for our kernel
            q_head_t = q_head.permute(1, 0, 2)  # (batch_size, seq_len, head_dim)
            k_head_t = k_head.permute(1, 0, 2)  # (batch_size, seq_len, head_dim)

            # Compute attention scores
            scores = torch.bmm(q_head_t, k_head_t.transpose(1, 2))  # (batch_size, seq_len, seq_len)
            attn_weights = torch.softmax(scores, dim=-1)

            # Apply attention weights to V
            head_output = torch.bmm(attn_weights, v_head_t)  # (batch_size, seq_len, head_dim)
            head_output = head_output.permute(1, 0, 2)  # (seq_len, batch_size, head_dim)
            attn_output_list.append(head_output)

        # Concatenate heads
        attn_output = torch.cat(attn_output_list, dim=2)  # (seq_len, batch_size, embed_dim)

        # Apply output projection
        attn_output = torch.nn.functional.linear(attn_output, self.attn.out_proj.weight, self.attn.out_proj.bias)

        # Residual connection and normalization
        x = self.norm(attn_output + x_seq)

        # Reshape back to (B, C, H, W)
        x = x.permute(1, 2, 0).view(B, C, H, W)

        return x

