__global__ void qk_matmul_kernel(
    const float* q, const float* k, float* attn,
    int batch_size, int num_heads, int seq_len, int head_size, float scale) {

    int b = blockIdx.z;  // Batch
    int h = blockIdx.y;  // Head
    int i = blockIdx.x * blockDim.x + threadIdx.x;  // Row in attention

