# Corrected attention kernel - focus on accuracy first
fused_attention_source = """
#include <hip/hip_runtime.h>

// Compute attention output matching PyTorch's reference implementation
// This kernel computes each output position's result by:
// 1. Computing attention scores for all positions
// 2. Applying causal mask
// 3. Applying softmax
// 4. Computing weighted sum of values

__global__ void causal_attention_kernel(
    const float* q, const float* k, const float* v, float* output,
    int B, int nh, int T, int hs
) {
    int b = blockIdx.z;
    int h = blockIdx.y;
    int t_out = blockIdx.x * blockDim.x + threadIdx.x;

    if (t_out >= T) return;

    // Base pointers for this batch and head
    const float* q_ptr = q + (b * nh + h) * (T * hs);
    const float* k_ptr = k + (b * nh + h) * (T * hs);
    const float* v_ptr = v + (b * nh + h) * (T * hs);
    float* out_ptr = output + (b * nh + h) * (T * hs);

    // Shared memory for softmax computation
    extern __shared__ float s_mem[];
    float* logit = s_mem;      // size T
    float* weight = s_mem + T; // size T  
    float* exp_sum = s_mem + 2 * T; // size 1 for reduction

    float scale = rsqrtf(float(hs));

    // Step 1: Compute attention scores (logits)
    for (int t_in = threadIdx.x; t_in < T; t_in += blockDim.x) {
        if (t_in > t_out) {
            logit[t_in] = -INFINITY;
        } else {
            // Compute dot product: q[t_out] @ k[t_in]
            float dot = 0.0f;
            for (int d = 0; d < hs; d++) {
                dot += q_ptr[t_out * hs + d] * k_ptr[t_in * hs + d];
            }
            logit[t_in] = dot * scale;
        }
    }

    __syncthreads();

    // Step 2: Find max for numerical stability (reduction)
    float max_val = -INFINITY;
    for (int t_in = 0; t_in < T; t_in++) {
        max_val = fmaxf(max_val, logit[t_in]);
    }

    // Step 3: Compute exp and sum (softmax)
    float sum_exp = 0.0f;
    for (int t_in = 0; t_in < T; t_in++) {
        if (t_in <= t_out) {
            float exp_val = expf(logit[t_in] - max_val);
            weight[t_in] = exp_val;
            sum_exp += exp_val;
        } else {
            weight[t_in] = 0.0f;
        }
    }

    // Handle edge case
    if (sum_exp == 0.0f) sum_exp = 1.0f;

    __syncthreads();

    // Step 4: Compute output as weighted sum over values
    for (int d = 0; d < hs; d++) {
        float out_val = 0.0f;
        for (int t_in = 0; t_in < T; t_in++) {
            if (t_in <= t_out) {
                out_val += (weight[t_in] / sum_exp) * v_ptr[t_in * hs + d];
            }
        }
        out_ptr[t_out * hs + d] = out_val;
    }
}

torch::Tensor fused_attention_hip(torch::Tensor q, torch::Tensor k, torch::Tensor v) {
    auto B = q.size(0);
    auto nh = q.size(1);
    auto T = q.size(2);
    auto hs = q.size(3);

    auto output = torch::zeros_like(q);

    const int block_size = 1; // One output position per thread
    dim3 blockDim(block_size);
    dim3 gridDim(T, nh, B);
    size_t shared_mem_size = (2 * T + 1) * sizeof(float);

    causal_attention_kernel<<<gridDim, blockDim, shared_mem_size>>>(
        q.data_ptr<float>(), 
        k.data_ptr<float>(), 
        v.data_ptr<float>(),
        output.data_ptr<float>(),
        B, nh, T, hs
    );

    return output;
}
"""

fused_attention = load_inline(
