# Fused Linear + GELU activation kernel
# This is simpler and more likely to be numerically correct
fused_linear_gelu_source = """
#include <hip/hip_runtime.h>

__global__ void fused_linear_gelu_kernel(
    const float* input, const float* weight, const float* bias,
    float* output,
    int batch, int seq, int in_dim, int out_dim
) {
    // output = GELU(input @ weight^T + bias)
    // weight shape: (out_dim, in_dim)
    // input shape: (batch, seq, in_dim)
    // output shape: (batch, seq, out_dim)

    int b = blockIdx.z;
    int s = blockIdx.y;
    int o = blockIdx.x * blockDim.x + threadIdx.x;

    if (o >= out_dim) return;

    // Compute dot product for this output neuron
    float sum = 0.0f;
    for (int i = 0; i < in_dim; i++) {
        // Input is row-major: (batch * seq * in_dim)
        int in_idx = (b * seq + s) * in_dim + i;
        // Weight is row-major: (out_dim * in_dim)
        int w_idx = o * in_dim + i;
        sum += input[in_idx] * weight[w_idx];
    }

    // Add bias
    sum += bias[o];

    // Apply GELU activation
    // GELU(x) = 0.5 * x * (1 + tanh(sqrt(2/pi) * (x + 0.044715 * x^3)))
    float x = sum;
    float x3 = x * x * x;
    float tanh_arg = 0.7978845608f * (x + 0.044715f * x3);  // sqrt(2/pi) ≈ 0.7978845608
    float gelu = 0.5f * x * (1.0f + tanhf(tanh_arg));

    int out_idx = (b * seq + s) * out_dim + o;
    output[out_idx] = gelu;
}

torch::Tensor fused_linear_gelu_hip(torch::Tensor input, torch::Tensor weight, torch::Tensor bias) {
    auto batch = input.size(0);
    auto seq = input.size(1);
    auto in_dim = input.size(2);
    auto out_dim = weight.size(0);

    auto output = torch::empty({batch, seq, out_dim}, input.options());

    const int block_size = 256;
    dim3 blockDim(block_size);
    dim3 gridDim((out_dim + block_size - 1) / block_size, seq, batch);

    fused_linear_gelu_kernel<<<gridDim, blockDim>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        batch, seq, in_dim, out_dim
    );

    return output;
}
"""

