        q, k, v = self.c_attn(x).split(self.n_embd, dim=2)
        k = k.view(B, T, self.n_head, C // self.n_head).transpose(1, 2)
        q = q.view(B, T, self.n_head, C // self.n_head).transpose(1, 2)
        v = v.view(B, T, self.n_head, C // self.n_head).transpose(1, 2)

        att = (q @ k.transpose(-2, -1)) * (1.0 / math.sqrt(k.size(-1)))
        att = att.masked_fill(self.bias[:,:,:T,:T] == 0, float('-inf'))
        att = torch.nn.functional.softmax(att, dim=-1)
        att = self.attn_dropout(att)
        y = att @ v
        y = y.transpose(1, 2).contiguous().view(B, T, C)
        y = self.resid_dropout(self.c_proj(y))

        return y


class MLPNew(nn.Module):
    """
    Optimized MLP with fused Linear + GELU kernel
    """
    def __init__(self, n_embd, resid_pdrop, fused_module):
        super().__init__()
        self.c_fc_weight = None
        self.c_fc_bias = None
        self.c_proj = nn.Linear(4 * n_embd, n_embd)
        self.dropout = nn.Dropout(resid_pdrop)
        self.fused_linear_gelu = fused_module
        self.n_embd = n_embd

        # Initialize c_fc as identity (no bias needed in init)
        self.c_fc = nn.Linear(n_embd, 4 * n_embd)

    def forward(self, x):
        # Use fused kernel for c_fc + GELU
        hidden = self.fused_linear_gelu.fused_linear_gelu_hip(
            x, self.c_fc.weight, self.c_fc.bias
        )
        # Standard linear projection and dropout
        y = self.c_proj(hidden)
        return self.dropout(y)


class ModelNew(nn.Module):
    """Optimized MiniGPT block with fused MLP kernel."""

    def __init__(self, n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen):
        super().__init__()
        self.fused_linear_gelu = fused_linear_gelu

        self.ln_1 = nn.LayerNorm(n_embd)
        self.attn = CausalSelfAttentionNew(n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen)
        self.ln_2 = nn.LayerNorm(n_embd)
        self.mlp = MLPNew(n_embd, resid_pdrop, self.fused_linear_gelu)

    def forward(self, x):
        x = x + self.attn(self.ln_1(x))
        x = x + self.mlp(self.ln_2(x))
        return x

import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import math
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# Optimized softmax kernel with causal masking built-in
masked_softmax_source = """
#include <hip/hip_runtime.h>

#define BLOCK_SIZE 128

__global__ void masked_softmax_kernel(
    float* attn,
    int batch_size, int num_heads, int seq_len) {

    int b = blockIdx.z;  // Batch
    int h = blockIdx.y;  // Head
    int i = blockIdx.x * blockDim.x + threadIdx.x;  // Row

    if (i >= seq_len) return;

    // Base for this attention row
    int row_base = (b * num_heads * seq_len + h * seq_len + i) * seq_len;

    // Find max
    float max_val = -1e20f;
    for (int j = 0; j < seq_len; j++) {
        float val = attn[row_base + j];
        max_val = fmaxf(max_val, val);
    }

    // Sum exp
    float sum_exp = 0.0f;
    for (int j = 0; j < seq_len; j++) {
        float val = attn[row_base + j];
        sum_exp += expf(val - max_val);
    }

    // Apply softmax
    float inv_sum = 1.0f / (sum_exp + 1e-6f);
    for (int j = 0; j < seq_len; j++) {
        float val = attn[row_base + j];
        attn[row_base + j] = expf(val - max_val) * inv_sum;
    }
}

torch::Tensor masked_softmax_hip(torch::Tensor attn) {
    auto batch_size = attn.size(0);
    auto num_heads = attn.size(1);
    auto seq_len = attn.size(2);

    int block_dim = BLOCK_SIZE;
    dim3 grid_dim((seq_len + block_dim - 1) / block_dim, num_heads, batch_size);

    masked_softmax_kernel<<<grid_dim, block_dim>>>(
        attn.data_ptr<float>(),
        batch_size, num_heads, seq_len
    );

    return attn;
}
"""

masked_softmax = load_inline(
    name="masked_softmax",
    cpp_sources=masked_softmax_source,
    functions=["masked_softmax_hip"],
    verbose=True,
)


class ModelNew(nn.Module):
    """
    An optimized multi-head masked self-attention layer using custom HIP kernels.
    Optimizes the softmax operation with integrated causal masking.
    """
    def __init__(self, n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen):
        super().__init__()
        assert n_embd % n_head == 0
        # key, query, value projections for all heads, but in a batch
        self.c_attn = nn.Linear(n_embd, 3 * n_embd)
        # output projection
        self.c_proj = nn.Linear(n_embd, n_embd)
        # regularization
        self.attn_dropout = nn.Dropout(attn_pdrop)
        self.resid_dropout = nn.Dropout(resid_pdrop)
        # causal mask to ensure that attention is only applied to the left in the input sequence
        self.register_buffer("bias", torch.tril(torch.ones(max_seqlen, max_seqlen))
                                     .view(1, 1, max_seqlen, max_seqlen))
        self.n_head = n_head
        self.n_embd = n_embd

        # Custom masked softmax kernel
        self.masked_softmax = masked_softmax

    def forward(self, x):
        B, T, C = x.size() # batch size, sequence length, embedding dimensionality (n_embd)

        # calculate query, key, values for all heads in batch and move head forward to be the batch dim
        q, k ,v  = self.c_attn(x).split(self.n_embd, dim=2)
        k = k.view(B, T, self.n_head, C // self.n_head).transpose(1, 2) # (B, nh, T, hs)
        q = q.view(B, T, self.n_head, C // self.n_head).transpose(1, 2) # (B, nh, T, hs)
        v = v.view(B, T, self.n_head, C // self.n_head).transpose(1, 2) # (B, nh, T, hs)

        # causal self-attention; Self-attend: (B, nh, T, hs) x (B, nh, hs, T) -> (B, nh, T, T)
        att = (q @ k.transpose(-2, -1)) * (1.0 / math.sqrt(k.size(-1)))
        att = att.masked_fill(self.bias[:,:,:T,:T] == 0, float('-inf'))

        # Use custom masked softmax kernel
        att = self.masked_softmax.masked_softmax_hip(att)

        att = self.attn_dropout(att)
        y = att @ v # (B, nh, T, T) x (B, nh, T, hs) -> (B, nh, T, hs)
        y = y.transpose(1, 2).contiguous().view(B, T, C) # re-assemble all head outputs side by side

        # output projection
        y = self.resid_dropout(self.c_proj(y))
        return y

import os
import torch
import torch.nn as nn
import math
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

# GELU activation kernel
gelu_source = """
#include <hip/hip_runtime.h>

__global__ void gelu_kernel(float* x, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = x[idx];
        // GELU(x) = 0.5 * x * (1 + tanh(sqrt(2/pi) * (x + 0.044715 * x^3)))
        float x3 = val * val * val;
        float tanh_arg = 0.7978845608028654f * (val + 0.044715f * x3);
        x[idx] = 0.5f * val * (1.0f + tanhf(tanh_arg));
    }
}

void gelu_hip(torch::Tensor x) {
    auto size = x.numel();
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;
    gelu_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), size);
}
"""

gelu_module = load_inline(
    name="gelu_activation",
    cpp_sources=gelu_source,
    functions=["gelu_hip"],
    verbose=True,
)


class NewGELUOptimized(nn.Module):
    """
    Optimized GELU activation with HIP kernel
    """
    def __init__(self, gelu_kernel_module):
        super().__init__()
        self.gelu_kernel = gelu_kernel_module

    def forward(self, x):
        y = x.clone()  # Don't modify in-place
        self.gelu_kernel.gelu_hip(y)
        return y


class CausalSelfAttentionNew(nn.Module):
    """
    Keep standard PyTorch attention for correctness
    """
    def __init__(self, n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen):
        super().__init__()
        self.c_attn = nn.Linear(n_embd, 3 * n_embd)
        self.c_proj = nn.Linear(n_embd, n_embd)
        self.attn_dropout = nn.Dropout(attn_pdrop)
        self.resid_dropout = nn.Dropout(resid_pdrop)
        self.register_buffer("bias", torch.tril(torch.ones(max_seqlen, max_seqlen))
                                     .view(1, 1, max_seqlen, max_seqlen))
        self.n_head = n_head
        self.n_embd = n_embd

    def forward(self, x):
        B, T, C = x.size()

        # Standard PyTorch attention
        q, k, v = self.c_attn(x).split(self.n_embd, dim=2)
        k = k.view(B, T, self.n_head, C // self.n_head).transpose(1, 2)
        q = q.view(B, T, self.n_head, C // self.n_head).transpose(1, 2)
        v = v.view(B, T, self.n_head, C // self.n_head).transpose(1, 2)

        att = (q @ k.transpose(-2, -1)) * (1.0 / math.sqrt(k.size(-1)))
        att = att.masked_fill(self.bias[:,:,:T,:T] == 0, float('-inf'))
        att = torch.nn.functional.softmax(att, dim=-1)
        att = self.attn_dropout(att)
        y = att @ v
        y = y.transpose(1, 2).contiguous().view(B, T, C)
        y = self.resid_dropout(self.c_proj(y))

        return y


class ModelNew(nn.Module):
    """Optimized MiniGPT block with optimized GELU activation."""

    def __init__(self, n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen):
        super().__init__()
        self.gelu_module = gelu_module

        self.ln_1 = nn.LayerNorm(n_embd)
        self.attn = CausalSelfAttentionNew(n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen)
        self.ln_2 = nn.LayerNorm(n_embd)
        self.mlp = nn.ModuleDict(dict(
            c_fc    = nn.Linear(n_embd, 4 * n_embd),
            c_proj  = nn.Linear(4 * n_embd, n_embd),
            act     = NewGELUOptimized(self.gelu_module),
            dropout = nn.Dropout(resid_pdrop),
        ))
        m = self.mlp
        self.mlpf = lambda x: m.dropout(m.c_proj(m.act(m.c_fc(x))))

    def forward(self, x):
        x = x + self.attn(self.ln_1(x))
        x = x + self.mlpf(self.ln_2(x))
        return x
